/**
 * Returns the transport cost of histogram {@code a} against histogram
 * {@code b}, two arrays of masses over the same unit-spaced bins, as
 * evaluated over the bins that hold mass.
 * <p>
 * The bins that hold mass in either histogram are first listed with
 * {@link Frequency#occupiedBins(double[], double[])}; the value returned is
 * exactly {@link Sum#carriedCost(double[], double[], int[])} applied to
 * {@code a}, {@code b} and that list.
 * </p>
 *
 * @param a masses of the first histogram, one entry per bin
 * @param b masses of the second histogram, at least as long as {@code a}
 * @return the transport cost
 */
public static double transportCost(final double[] a, final double[] b) {
    return Sum.carriedCost(a, b, Frequency.occupiedBins(a, b));
}

